const b = $input.first().json.body || {};
const h = $input.first().json.headers || {};
if (h['x-l10n-secret'] !== 'f41b7c2e9d0a83561e2b4c7d9a0f13e8') throw new Error('bad secret');
if (!['one','all'].includes(b.mode)) throw new Error('bad mode');
if (!/^[0-9a-f]+\.[0-9]+$/.test(b.pid || '')) throw new Error('bad pid');
const T = b.T || [];
const ids = [...new Set(T.map(t => t[0]))];
return [{ json: { mode: b.mode, pid: b.pid, status: b.status_id || null, T, ids: ids.join(',') } }];

const cfg = $('Params').first().json;
const live = {};
for (const k of ($('Get Current').first().json.keys || [])) { const m = {}; for (const t of (k.translations||[])) m[t.language_iso] = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); live[k.key_id] = { m, arch: k.is_archived }; }
const per = {}; const held = [];
for (const [id, iso, en, tr] of cfg.T) {
  const L = live[id];
  if (!L || L.arch) { held.push([id, iso, 'missing/archived']); continue; }
  if ((L.m.en || '') !== en) { held.push([id, iso, 'EN changed']); continue; }
  if ((L.m[iso] || '').trim()) { held.push([id, iso, 'already filled']); continue; }
  const t = { language_iso: iso, translation: tr, is_unverified: true };
  if (cfg.status) t.custom_translation_status_ids = [cfg.status];
  (per[id] = per[id] || []).push(t);
}
let keys = Object.keys(per).map(id => ({ key_id: Number(id), translations: per[id] }));
if (cfg.mode === 'one') keys = keys.slice(0, 1);
const out = []; for (let i = 0; i < keys.length; i += 40) out.push({ json: { body: { keys: keys.slice(i, i + 40) }, n: keys.slice(i, i + 40).reduce((a, k) => a + k.translations.length, 0), held } });
if (!out.length) throw new Error('nothing to write: ' + JSON.stringify(held.slice(0, 20)));
return out;

const cfg = $('Params').first().json;
const live = {};
for (const k of ($('Read Back').first().json.keys || [])) for (const t of (k.translations||[])) live[k.key_id + '|' + t.language_iso] = t;
const per = {}; let match = 0, unver = 0, status = 0; const diff = [];
for (const [id, iso, en, tr] of cfg.T) { const t = live[id + '|' + iso] || {}; per[iso] = per[iso] || 0; if (t.translation === tr) { match++; per[iso]++; if (t.is_unverified) unver++; if (cfg.status && (t.custom_translation_statuses || []).some(s => s.status_id === cfg.status)) status++; } else diff.push([id, iso]); }
const b = $('Build').all();
return [{ json: { sent: b.reduce((a, i) => a + i.json.n, 0), held: b[0].json.held.length, heldSample: b[0].json.held.slice(0, 10), matchNow: match, perLang: per, unverified: unver, withStatus: status, notMatching: diff.length } }];
